@push('scripts')<script>
const start=document.getElementById('startTime'),duration=document.getElementById('duration'),end=document.getElementById('endTime'),total=document.getElementById('estimatedTotal');
const rates=@json($ratePayload);
if(!rates.length)rates.push({start:'{{substr($asset->rental_open_time,0,5)}}',end:'{{substr($asset->rental_close_time,0,5)}}',rate:{{(float)$asset->hourly_rate}}});
function calculate(){let amount=0,valid=true;if(start.value&&duration.value){const [h,m]=start.value.split(':').map(Number),begin=h*60+m,finish=begin+(Number(duration.value)*60);end.value=String(Math.floor(finish/60)%24).padStart(2,'0')+':'+String(finish%60).padStart(2,'0');let cursor=begin;while(cursor<finish){const tier=rates.find(item=>{const [sh,sm]=item.start.split(':').map(Number),[eh,em]=item.end.split(':').map(Number);return cursor>=sh*60+sm&&cursor<eh*60+em});if(!tier){valid=false;break}const [eh,em]=tier.end.split(':').map(Number),segmentEnd=Math.min(finish,eh*60+em);amount+=((segmentEnd-cursor)/60)*Number(tier.rate);cursor=segmentEnd;}}total.textContent=valid?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(amount):'Waktu di luar rentang tarif';total.classList.toggle('text-danger',!valid)}
start.addEventListener('input',calculate);duration.addEventListener('input',calculate);const usage=document.getElementById('usageType'),other=document.getElementById('otherUse');function usageToggle(){other.classList.toggle('d-none',usage.value!=='Lainnya');other.querySelector('input').required=usage.value==='Lainnya'}usage.addEventListener('change',usageToggle);calculate();usageToggle();
</script>@endpush